INSERT INTO `submissions` (`submission_id`, `object`, `user_id`, `web_id`, `is_scientific`, `url`, `actual_url`, `title`, `content`, `keywords`, `metadescription`, `problem`, `problem_p`, `problem_exp`, `problem_exp _p`, `problem_importance`, `problem_importance_p`, `problem_importance_exp`, `prev_solution_1`, `prev_solution_1_p`, `prev_solution_2`, `prev_solution_2_p`, `prev_solution_3`, `prev_solution_3_p`, `prev_solution_drawback_1`, `prev_solution_drawback_1_p`, `prev_solution_drawback_1_exp`, `prev_solution_drawback_2`, `prev_solution_drawback_2_p`, `prev_solution_drawback_2_exp`, `prev_solution_drawback_3`, `prev_solution_drawback_3_p`, `prev_solution_drawback_3_exp`, `sloution`, `sloution_p`, `name`, `sloution_exp`, `sloution_advantage_1`, `sloution_advantage_1_p`, `sloution_advantage_1_exp`, `sloution_advantage_2`, `sloution_advantage_2_p`, `sloution_advantage_2_exp`, `solution_part_1`, `solution_image_1`, `solution_image_caption_1`, `solution_part_2`, `solution_image_2`, `solution_image_caption_2`, `solution_part_3`, `solution_image_3`, `solution_image_caption_3`, `solution_part_4`, `solution_image_4`, `solution_image_caption_4`, `solution_part_5`, `solution_image_5`, `solution_image_caption_5`, `solution_part_6`, `solution_image_6`, `solution_image_caption_6`, `solution_part_7`, `solution_image_7`, `solution_image_caption_7`, `solution_final_part`, `solution_advantages`, `conclusion`, `ref_authors_1`, `ref_article_title_1`, `ref_journal_title_1`, `ref_vol_issue_1`, `ref_authors_2`, `ref_article_title_2`, `ref_journal_title_2`, `ref_vol_issue_2`, `ref_authors_3`, `ref_article_title_3`, `ref_journal_title_3`, `ref_vol_issue_3`, `authors`, `affiliation`, `publisher`, `issn`, `email`, `country`, `related_links_1`, `related_links_text_1`, `related_links_2`, `related_links_text_2`, `related_links_3`, `related_links_text_3`, `submitted`, `rejected`, `published`, `scan_id`, `scan_status`, `is_duplicated`, `duplicate_percentage`, `similar_results`, `used_credits`) VALUES
(176, 'Article', 18, 'clamamagazine.com', '1', 'A-Novel-Airborn-Multi-Turbin-Floating-Wind-Energy-Generator', '', 'A Novel Airborn Multi-Turbin Floating Wind Energy Generator', 'This is test', 'Global warming, wind energy, wind turbin, electrical generator, efficiency, electrical generator, airborne energy', 'The ground mounted wind turbines extract low wind energy To increase the wind energy extraction efficiency a new airborn multi wind turbin generator is proposed', 'The ground mounted wind turbines extract low wind energy', 'The air friction with the earth surface is high because of mountains, buildings, trees which reduces the wind speed, and wind turbines extract a low energy', 'The low altitude winds are low speed because of air friction with earth surface. They have a low wind energy.', '', 'The increasing trend of energy consumption causes the wind energy become important but it energy extraction still is in amount and wind energy plans may not satisfy the future energy need', 'Every year countires parliment legislate wind energy plans but because almost all these plans are ground mounted wind turines they extract not enough energy and hardly satisfy the plan pupose', 'The human civilication energy need is increasing and the movement to the wind power extraction started but still this technology is not matured enoug and it cannot extract the needed energy from the wind', 'The contra rotor wind energy generators the benefits two wind turbines and has higher wind energy extraction ratio.', 'Convetional wind turbines has a single turbine but contra-rotor wind turbines has two turbine which are connected as both sides of an type of eletrical generator that has two shafts', 'The flying kite energy which uses kites pushed by wind flow and it pulls a string and the string turns shaft of an electrical generator', 'Flying kite have a wind area that can collect more wind energy. The flying kite can extract 40 times more energy than a similar wind turbin with the same cost. Flying kite will be flying at sky and it pulles a string that turns an electrical generator', 'The floating savious style wind turbines that floating at high altitude and generate electricity send to ground via a conductive tether', 'Inflatable cyrlandircal shabed wind turbines rotate around their horizontal axis and rotate a generate connected to it. This wind turbine are savrnois style wind tubine but are filled with helium gas and float at a high altitude and tranmit generated elecgtrcity to the ground via a enforced cable', 'These wind turbines are complicate to manufacture and still work at low altitude or monuted on the ground which extract low wind energy', 'Although this contra rotor wind turbines extract more energy but the wind speed near ground surface is weak that is generate still not satifying wind energy', 'The contra roto wind tubines has uses a generator that has two rotors inside and so this generator has two shaft and one wind turbine is connected to each shaft. It will have totally two wind turbines and they rotate when wind blow but in opposite directions because the blade angle of the two turbines designed to be in opposit.', 'The flying kit are hard to control as they become untasable in high wind speeds', 'These flying kite at sky need to be controlled and their pitch angle is controlled. Because when they ascend their pitch angle is andjusted so it collected wind energy, and it descend its pitch angle is controlled so it does not collect wind energy and it easily come to back to ground station. In fact, the flying kite should be controlled so that it perodically ascend and descend from the ground', 'The flying kite although has a high energy extraction ratio but they need a complicated control strategy to control their pitch angle during operation', 'The consruction of damm are costly and not possible everywhere', 'Damms are costy, because damms need a huge amount of construction materials and takes a long time to construct. It also need tranmission line to deliver electrixal energy to the national grid.', 'The floating savonus wind turbine are cyladrical shap wind turbines that filled with lighter than air gas and they are floating at high altitude ', 'To increase the wind energy extraction efficiency a new airborn multi wind turbin generator is proposed', '', '', 'The high altitude winds are persistent and stronger than low altitude winds and the proposed wind turbin in this paper will operate at high altitudes extracts higher wind energy compared to ground mounted wind turbines', 'The new wind turbine extract more wind energy as it will be at high altitude', '', 'When at ground there wind are weak or not persistent, this propsoed wind turbine in in exposure of high altitude high speed wind and generates electrical energy tranmit to earth', 'The wind turbin is low cost and also need minimum structural materials and  small ground.', '', 'When at ground there wind are weak or not persistent, this propsoed wind turbine in in exposure of high altitude high speed wind and generates electrical energy tranmit to earth', 'The proposed wind turbine consisted of an array of floating wind turbine. Each of the wind turbines is a light weight wind turbine with a light weight permanent magnet electrical generator. This wind turbine is framed with an inflatable round structure filled with a lighter than air gas allow it be aloft as shown in Fig.1', 'The-floating-ligh-weight-wind-turbine-generator-framed-with-a-inflatable-circular-ballon-filled-with-lighter-than-air-gas.png', 'The floating ligh weight wind turbine generator framed with a inflatable circular ballon filled with lighter than air gas', 'The used electrical generator is a DC permanent magnet generator which an aluminum envelop and aluminum shaft. The generator is designed to be light weight. The generator has two series axial flux generators inside with co-axis shaft connected to the main shaft', 'Light-weight-electrical-generator-with-aluminum-made-shaft-and-envelop.png', 'Light weight electrical generator with aluminum made shaft and envelop', 'Multiple number of the described floating turbines are connected together and framed in an rectangular aluminum frame. The whole structure will be floating at high altitude. The electrical generators terminals are connected together in parallel connected and whole multiple wind turbine will have two output terminals which is a single phase DC current', 'Multiple-floating-wind-turbines-framed-in-an-rectangular-aluminum-frame-floating-at-high-altitude.png', 'Multiple floating wind turbines framed in an rectangular aluminum frame floating at high altitude', 'The tether connect the multi-wind turbine system to the ground is a conductive wire coated with cotton. Three strong fibers also are inside of the cotton. Also, a data cable included inside the cotton as all shown in Fig.4. The data cable is for sensing the condition of the electrical generators and monitoring them for possible incident fault detection', 'The-tether-has-an-condutive-wire-and-three-strong-ligh-weigh-carbon-fibers-and-data-cabel-coated-with-cotton.png', 'The tether has an condutive wire and three strong ligh weigh carbon fibers and data cabel coated with cotton', 'The generated electrical energy by the wind turbines is transferred via a conductive tether to the ground as shown in Fig. 3. The whole structure will be floating at high altitude and it will benefit from high altitude winds with high speed, persistence speed in other words high wind energy density', 'The-generated-wind-energy-is-transfered-to-ther-ground-via-the-conductive-tethers.png', 'The generated wind energy is transfered to ther ground via the conductive tethers', 'The tether connect the floating muti-wind turbine system to the ground station. This ground station has foundation and on this foundation a drum control the tether length. For reducing the tether length the drum turns and tether is turned around the drum. For increasing the tether length to increase the floating multi-wind turbine system the drum turns in opposite direction and released the tether. The generated electricity then is transferred to a power transformer  as shown in Fig.6. This is a step up power transformer increase the the voltage. The voltage increase because it should be compatible with grid voltage. The other reason for increasing the volatile is that because the electrical energy should be transferred the high voltage will have lower electrical loss at transmission line. At the consumption point, the electrical voltage again will be reduced to be compatible with consumer electrical or electronic devices', 'The-ground-station-receives-the-electrical-energy-via-the-tether-and-also-control-the-tether-length-The-electrical-voltage-is-increased-by-step-up-power-transformer-to-be-fed-into-grid.png', 'The ground station receives the electrical energy via the tether and also control the tether length The electrical voltage is increased by step up power transformer to be fed into grid', 'A floating wind farm will be at high altitude by using several number of such floating multi-wind turbine systems. The generated electricity by such wind turbines is transferred to their corresponding ground stations and collected together to be fed into electrical grid', 'A-high-altitude-floating-wind-farm-consisted-of-several-floating-multi-wind-turbine-generator.png', 'A high altitude floating wind farm consisted of several floating multi wind turbine generator', '', 'The proposed wind turbine has a lower cost as it does not need foundation, tower, gearbox and large ground area compared to ground mounted wind turbine. It also generate more electrical energy as it benefit from high altitude winds with high wind speed. Also, in contrast to the ground mounted wind turbines and wind farms that has beauty issues for the nature this wind turbine will be at high al;attitude not visible by naked eyes', 'The current wind energy technology is not cable of extract considerable wind energy although the human energy consumption increases. In this paper a new floating multi-wind turbine system proposed. The proposed wind turbine consisted an array of floating wind turbines that framed with an circular lighter than air structure. The electrical energy is generated by the wind turbine and are transmitted to a ground station via a conductive enforced tether, where the electrical voltage is increases by power transformer to be fed to national grid', 'Saeed Tehrani', 'New Global Warming', 'Journal of Energy', 'vol. 2. Issue.1', 'John Smith, Reyhan Saaed', 'New Way to Green House', 'Journal of Renewable and Sustainable Energy', 'Vol.3 Issue.3', 'Mohammad Sabir, Mohan Zakir', 'How to increase wind energy efficicieny', 'International Journal of Energy', 'Vol.4, Issue.5', 'Saeed Rahmani, Ali Ghambari', '', '', '', '', '', '', '', '', '', '', '', 1, 0, 1, '388869', 'success', '', '0', '', '1'),
(177, 'author', 0, 'science-score.org', '', 'abbas-rezaey', '', NULL, NULL, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Abbas Rezaey', 'Department of Computer and Communications Technology', '', '', 'abbas.rezaey1@gmail.com', '', '', '', '', '', '', '', 1, 0, 1, '', '', '', '', '', ''),
(178, 'Article', 18, 'clamamagazine.com', '1', 'A-New-Speed-Breaker-System-RBS-as-Renewable-Energy-Generator', '', 'A New Speed Breaker System (RBS) as Renewable Energy Generator', 'The speed breaker generator has a linear moving electrical generator which is moved down once a car passes over it. It consisted of a speed breaker which is connected to the linear generator.', 'Speed breaker, electrical energy generation, renewable energy, electrical generator, , Speed breaker, electrical energy generation, renewable energy, electrical generator, distributed energy generation', 'The amount of extracted energy from fossil fuels and renewable energies is limited A new speak breaker proposed and generates electricity by pressure of cars weight pressing the speed breaker', 'The amount of extracted energy from fossil fuels and renewable energies is limited', 'The fossile fuels consisted of coal and oil which are extracted from underground and these are limitted will end by end of the centry', 'Fossile fuel resources is limitted and also renewable energy generation is difficualt and there are limiation in solar power, water power, and biomass energy generation as they are not unlimited and constant flow of energy', '', 'The energy is vital need of civilization The cities works with electricitiy', 'The human civilization highly depends on the electrcity and without it the civilization will face serious problems', 'A huge part of cities works with electricty from home devices and city electrical parts from industry to travel and goverment offices', 'Wind energy generators including gorund mouted and floating ones are propsoed', 'The wind energy extraction both at high altides and low altitude, and over the ground proposed.', 'Water energy system benefirs water energy of rivers, sea, and damm ', 'The water energy uses flow of river, sea, or wave. The water energy moslt rotate a turbine to rotate a normal generator or moves an sliding generator.', 'Solar energy panel with high efficiency proposed', 'Solar energy extraction with solar panel propsoed and the efficiecny of solar panels increased by the time', 'Due to stochastic nature of wind energy, the wind enery is not steady and varies but situation if it is windy or not ', 'The wind energy is not predictable and it changes by the time and so it is not reliable energy and more resources of energy is needed to compensate when its is not windly as alternative', 'Ground  mounted wind turbines occupies large area and also floating wind farms are complicated to deply and control', 'The water energy is not possible anywhere', 'The water energy is feasible only in area that high pressure flow of water exist. ', 'Water energy need large and costy structures not possible everywhere', 'These solar panels only generates electricty during day and when is not cloudy', 'The solar panel need to be under radiation of the sun rays this energy extraction is possible during day or when the weather is not cloudy', 'The solar panels are expensive', 'A new speak breaker proposed and generates electricity by pressure of cars weight pressing the speed breaker', '', '', 'This speed braker system can be installed instead of the normal speak breakers', 'This is new source of energy not exploited yet', '', 'Still conventional speed breaker cannot generate electricty and it can be a new source of energy extracting from flow of the cars energy wasted on speed breakers', 'The generated electricty can be cosumed locally by street lights', '', 'Still conventional speed breaker cannot generate electricty and it can be a new source of energy extracting from flow of the cars energy wasted on speed breakers', 'The speed breaker energy generator works based on this principle that when car passes the speed breaker it pressed down and sliding electrical generators inside it generates electricity. The sliding electrical generators inside it can be described in this way that is has a sliding part and stationary part. The sliding and stationary parts are shown in Fig.1. The sliding part is over the stationary part. The sliding part made of iron and it has circular shaped poles as seen in the image.', 'The-sliding-generator-inside-the-speed-breaker-generator-consisted-of-two-parts-sliding-and-stationary-parts.png', 'The sliding generator inside the speed breaker generator consisted of two parts: sliding and stationary parts', 'The stationary part is similar to stator in electrical generators because it is stationary and has windings on its poles. The windings on its poles shown in Fig.2 and coils (windings) are shown in red color in the image. The coils are connected together in parallel electrical connected as shown in the image', 'The-stationary-part-which-has-poles-with-coils-connected-together-via-wire.png', 'The stationary part which has poles with coils connected together via wire', 'The speak breaker generator has three sliding generators as shown in Fig.3. These sliding generators are connected together electrically in series so their voltages are added together.', 'The-speaker-breaker-generator-has-3-sliding-generator-inside-it.png', 'The speaker breaker generator has 3 sliding generator inside it', 'The three sliding generators are connected to the conventional speed breaker indicated as yellow in the Fig.4. This speaker breaker is pressed down once a car passes over it and it slide down the sliding generators and they generates electrical energy', 'The-speed-beaker-connected-over-the-three-sliding-generators-and-presses-the-generators-down-once-a-car-passes.png', 'The speed beaker connected over the three sliding generators and presses the generators down once a car passes', 'This speed breaker electrical generator will look the same as conventional speed breakers as seen in Fig.5. The only difference is that under ground the sliding generators are positioned.', 'The-proposed-speed-breaker-generator-will-look-the-same-as-conventional-speed-breakers.png', 'The proposed speed breaker generator will look the same as conventional speed breakers', 'Once the car wheels passes over the speed breaker it is pushed down the electrical generators are pressed down and they generate electrical energy.', 'The-car-passes-over-the-speaker-breaker-and-it-generates-electrical-energy.png', 'The car passes over the speaker breaker and it generates electrical energy', 'When the speed breaker is pushed down, it should get back to original position. For this purpose three elastic thick bars are considered and positioned inside the system as seen in Fig.7. These three parts act similar to spring and return back the speaker breaker to the normal mode.', 'The-elestic-bars-that-push-back-the-speed-backer-to-teh-default-postion-after-the-car-passed.png', 'The elestic bars that push back the speed backer to teh default postion after the car passed', '', 'This speed breaker generator generates electricity locally in streets can be consumed locally by street lights. This reduce the cost of delivering electrical energy to these streets. Also, the electrical loss in transmission lines will not happen because the speed breaker generates electricity and it consumed there without need to transmission  to distant locations. Also, there are huge number of speed breakers in cities and road that can be replaced with this new speed breaker and will generates electricity. In fact the car flow energy is not exploited practically but this speed breaker electrical generator allow extraction of the cars flow practically and not experimentally like before', 'There is active movement toward clean energy generation as the oil and coal resources are dangerous for nature and also are limited will end soon. One of the energy resources which is not exploited commercially is the wasted energy in speed breakers. In this paper a novel speed breaker electrical generator proposed. Its operation principle explained and its parts illustrated. Finally its advantages are discussed.', 'M Partodezfoli, A Rezaey, Z Baniasad, H Rezaey', 'Journal of Basic and Applied Scientific Research', 'A novel speed-breaker for electrical energy generation suitable for elimination of remote parts of power systems where is near to roads', 'Vol. 2. Issue.10', 'Alok Kumar Singh, Deepak Singh, Madhawendra Kumar, Vijay Pandit', 'Generation of Electricity through Speed Breaker Mechanism', 'International Journal of Innovations and Engineering and Technology', 'Vo.1, Issue. 12', 'D.Venkata RaoȦ, K.Prasada RaoȦ, S.Chiranjeeva RaoȦ and R.Umamaheswara Rao', 'Design and Fabrication of Power generation System using Speed Breaker', 'International Journal of Current Engineering and Technology', '', 'Johan Hartlap, Caroline Shultze', '', '', '', '', '', '', '', '', '', '', '', 1, 0, 1, '', '', '', '', '', ''),
(179, 'Article', 18, 'clamamagazine.com', '1', 'A-new-Floating-Wind-Energy-Generator', '', 'A new Floating Wind Energy Generator', '<div style=\"margin-bottom:10px\">\r\n    This new wind turbine is floating at high altitude and consisted of several parts. The first part is a cicular inflatable structure as seen in the image Fig.1.\r\n    This circular part that is filled with a lighter than air gas and is floating over the ground at a high altitude. This structure has four aluminum rings.\r\n    These ring keeps the strengthen the the circular structures. There are four aluminum bars also as diameter of the the circular structure. \r\n    The diamtere of structure is 10 meters.\r\n    The thinkess of the structure is 4 meters.\r\n</div>\r\n<center><img  style=\"margin-bottom:10px; width:50%\" src=\"http://clamamagazine.com/images/1.png\">\r\n<div style=\"margin-bottom:10px\">Fig. 1. The circular structure filled with helium gas lighter than air gas keeps is floating at a high altitude.</div></center>\r\n\r\n<div  style=\"margin-bottom:10px\">\r\n    The second part is a metal bar connects the center of circular structure to ground based generator as seen in Fig.2. This metal bar is made of compressed carbon.\r\n    It is light weight and strong. It acts as the shaft of the circulart structure and when the circular structure turns the bar also turns.\r\n</div>\r\n<center><img src=\"http://clamamagazine.com/images/2.png\"  style=\"margin-bottom:10px; width:50%\">\r\n<div style=\"margin-bottom:10px\">Fig. 2. The shaft of the ciruclar structure which is a strong light weight bar.</div></center>\r\n\r\n<div  style=\"margin-bottom:10px\">\r\n    The third part is a electrical generator positioned on the ground and it is turned by the metal bar as its prime mover as shown in Fig.3. \r\n    It is a permanent magnet electrical generator.\r\n    The generator is fixed on the ground. The genertor shalf is connected via joint to the carbon-bar (shaft of the circular structure).\r\n    This joint allows the bar to rotate the electrical generator shaft at different angles. \r\n    Because the shaft of the circular structure is not vertically connected to electrical generator shaft.\r\n    Depends on the wind speed the ciruclar structure causes the carbon-bar aligns at different angles compared to the ground. \r\n \r\n</div>\r\n<center><img src=\"http://clamamagazine.com/images/3.png\"  style=\"margin-bottom:10px; width:50%\">\r\n<div style=\"margin-bottom:10px\">Fig. 3. The ground-based electrical generator that is rotated by the shaft of the circular structure.</div></center>\r\n\r\n<div>\r\n The third part is the Gas Filled Savonius Style (GFSS) wind turbine are connected to the circular structure and they turn it.\r\n GFSS are cylandrical shap structure that is filled with ligher than air gas. \r\n This type of wind turbines are savious shape wid turbine.\r\n It turns around its horizontal axis. \r\n GFSS has diamtere of 3 meters and length of 6 meters.\r\n The GFSS wind turine not only pull the circular structure but also turns around itself because a small permanent magnet generator is connected to the shaft of this GFSS wind turbine.\r\n One one of such GFSS wind turbine connected to the circular structure shown in Figure 4.  \r\n</div>\r\n<center><img src=\"http://clamamagazine.com/images/4.png\"  style=\"margin-bottom:10px; width:50%\">\r\n<div style=\"margin-bottom:10px\">Fig. 4. Gas Filled Savonius Style (GFSS) wind turbin connected to the circular structure. \r\n</div></center>\r\n\r\n<div style=\"margin-bottom:10px\">\r\nIn fact totally 7 GFSS wind turbines are connected to the cicular structure. \r\nOnce the wind blows, these turbines not only rotate around and generates electricty but also they pull the circular struture and rotate it as well as shown in Fig.5.\r\n</div>\r\n<center><img src=\"http://clamamagazine.com/images/5.png\"  style=\"margin-bottom:10px; width:50%\">\r\n<div style=\"margin-bottom:10px\">Fig. 5. Severn GFSS wind turbines connecred to the ciruclar structure.</div></center>\r\n\r\n<div style=\"margin-bottom:10px\">\r\nAs seen in Fig.6, the GFSS wind turbines are floating at a higher altitude than the circular structure. \r\nThey are tetherd to the cicular structure. \r\nEach GFSS wind turbine is connected to the cicular structure using two tethers as shown in Fig. 6.\r\n</div>\r\n<center><img src=\"http://clamamagazine.com/images/7.png\"  style=\"margin-bottom:10px; width:50%\">\r\n<div style=\"margin-bottom:10px\">Fig. 6. The seven GFSS wind turbines rotate altogether the ciruclar structure causes rotation of the carbon-bar rotates the ground based generator.</div></center>\r\n\r\n<div>\r\nThe generated electricity by the generator of the GFSS wind turbin transferred to the circular structure via the tethers and then from there is tranfered to ther ground via that bar becase a cable also is inside of the bar.\r\nAt the ground station, two electrical brushes get the electrical energy from the bar. \r\nIn fact the long bar transfer both electrical and also machnical energy.\r\n</div>\r\n<center><img src=\"http://clamamagazine.com/images/6.png\"  style=\"margin-bottom:10px; width:50%\">\r\n<div style=\"margin-bottom:10px\">Fig. 7. The carbon-bar transfers both electrical energy and mechanical energy from the floating circular structure to the ground.</div></center>\r\n\r\n<div>\r\nConsidering a 10 meter diameter circular structure and thinkess of 4 meters, with GFSS turbine with diamtere of 3 meteres and lenght of 6 meters, the generated electricty at wind speed of 30km/h will be 18KWh.\r\nAt very high speed the deviation angle of whole floating wind turbin to the ground will be low but it still will be at a high altitude and generates electricty according to calculations.\r\nA floating wind farm using such new floating windturbin also designed and its output power stimated. A wind farm with area of 1km x 1km with 200 number of such wind turbine can generate 3600Kwh in wind speed of 30k/h.\r\n</div>\r\n', 'floating wind farm, wind turbine, wind power, electrical generator', 'The global energy resources is limited Also this limited energy resources causes greenhouse effect Multi wind turbine  wind energy generator This wind tubines consisted of a circular inflatable that is floating but turned by several cylindrical wind turbines turning the circular system', 'The global energy resources is limited Also this limited energy resources causes greenhouse effect', 'The energy resources worldwide is ending and they releases green house gases causes the earth get warmer', 'It is estimated the fossil fuel energy last by future 50 years', 'The fossil resources will be finished by end of the century definitely', 'Energy is vital need of civilization and without it all aspects of civilization endangered Also, the greenhouse effect of current energy resources have an adverse effect on environment', 'Energy is the key need of human life now and any interuption in electricty can have adverse effect on several aspects of human life Also, current fossile fuel resources causes the earth temprature get higher and changes climate patterns into danrous climate pattern for nature and biological creature including human', 'The consumers in cities increase as the cities expanded and population increases The greenhouse effect of fossil fuel also makes the earth warmer', 'Ground mounted wind turbines that are installed on the ground has tower and wind turbine positioned on top of it  turning', 'The wind turbines that installed on the ground and it has a tower with a windturbin on top of it connected to an electrical generator', 'Floating inflatable wind turbines that filled with helium gas and tethered to the ground using a conductive tether The wind turbines turns and generates electricity transferred to the ground station via the tether ', 'Floating cylandrical wind turbines that are empty and filled with a ligher than air gas like helum gas and tetherd to the ground using a the tether and this tether also has a cable inside  These floating wind turbine rotate around their axis and produce electricity This electricity is transferred to the ground via that cable inside the tether', 'Flying kites that are pulled by wind and it turns a ground mounted electrical generator generates electricity', 'The kites that are flying in the air and they pul a tether when wind blows and this tether becuse is turned around a drumi its turns the drum connected to an electrical generator on the ground  generates electricity', 'Ground mounted wind turbines need large amount of structural materials', 'The wind turbines that installed on the ground rquire large amount of structural materials for tower and foundation', 'It needs a costing foundation and installation cost', 'The floating wind turbine has a low mechanical efficiency because of the shape of the wind turbine', 'The wind turbine which are cylandrical filled with ligher than air gas and are floating has a low mechanical efficiency due to this fact that they have a savonious style shape which has low efficiency', 'These wind turbines also can only operate at a low altitude as the tether length cannot increases due to its raising weight', 'Flying kites are hard to control and needs a complicated stablizing mechnism and sometimes the kites get out of the control', 'Flying kites energy generators need a complex control strategy and also not always this control strategy gurantees stability of it as the kiy flying in the air in higher wind speeds is unpredictable and very rotational', 'The kite located at low altitude and it occupies a large territory', 'Multi wind turbine  wind energy generator This wind tubines consisted of a circular inflatable that is floating but turned by several cylindrical wind turbines turning the circular system', 'A floating wind turbine with multiple floating wind turbines connected to it proposed. This wind turbine is has floating circular structure as the main  body that seven other floating wind turbines are connected to it and rotate it.', '', 'This wind turbine can operate in high altitude where stronger wind blow', 'It has a higher mechanical efficiency', 'It has a significat mechanical efficiency because of its structure', 'The wind turbine uses cylindrical wind turbines filled with lighter than air gas that has a large energy production efficiency', 'It is easier to control and stabilize', 'This wind turbin is alway aloft and it will not reach the ground and the only problem remains is controling the pitch angles of the seven wind turbines in different wind speed. This wind turbine is more stable than flying kites.', 'The wind turbine uses cylindrical wind turbines filled with lighter than air gas that has a large energy production efficiency', 'This new wind turbine is floating at high altitudes and consisted of several parts The first part is a cicular inflatable structure as seen in the image Fig1 This circular part that is filled with a lighter than air gas and is floating over the ground at a high altitude This structure has four aluminum rings These ring keeps the strengthen the the circular structures There are four aluminum bars also as diameter of the the circular structure The diamtere of structure is 10 meters The thinkess of the structure is 4 meters ', '1.png', 'The circular structure filled with helium gas lighter than air gas keeps is floating at a high altitude', 'The second part is a metal bar connects the center of circular structure to ground based generator as seen in Fig2 This metal bar is made of compressed carbon It is light weight and strong It acts as the shaft of the circulart structure and when the circular structure turns the bar also turns', '2.png', 'The shaft of the ciruclar structure which is a strong light weight bar', 'The third part is a electrical generator positioned on the ground and it is turned by the metal bar as its prime mover as shown in Fig3 It is a permanent magnet electrical generator The generator is fixed on the ground The genertor shalf is connected via joint to the carbon-bar (shaft of the circular structure) This joint allows the bar to rotate the electrical generator shaft at different angles Because the shaft of the circular structure is not vertically connected to electrical generator shaft Depends on the wind speed the ciruclar structure causes the carbon-bar aligns at different angles compared to the ground', '3.png', 'The ground-based electrical generator that is rotated by the shaft of the circular structure', 'The third part is the Gas Filled Savonius Style (GFSS) wind turbine are connected to the circular structure and they turn it GFSS are cylandrical shap structure that is filled with ligher than air gas This type of wind turbines are savious shape wid turbine It turns around its horizontal axis GFSS has diamtere of 3 meters and length of 6 meters The GFSS wind turine not only pull the circular structure but also turns around itself because a small permanent magnet generator is connected to the shaft of this GFSS wind turbine One one of such GFSS wind turbine connected to the circular structure shown in Figure 4', '4.png', 'Gas Filled Savonius Style (GFSS) wind turbin connected to the circular structure', 'In fact totally 7 GFSS wind turbines are connected to the cicular structure Once the wind blows, these turbines not only rotate around and generates electricty but also they pull the circular struture and rotate it as well as shown in Fig5', '5.png', 'Seven GFSS wind turbines connecred to the ciruclar structure', 'As seen in Fig6, the GFSS wind turbines are floating at a higher altitude than the circular structure They are tetherd to the cicular structure Each GFSS wind turbine is connected to the cicular structure using two tethers as shown in Fig 6', '7.png', 'The seven GFSS wind turbines rotate altogether the ciruclar structure causes rotation of the carbon-bar rotates the ground based generator', 'The generated electricity by the generator of the GFSS wind turbin transferred to the circular structure via the tethers and then from there is tranfered to ther ground via that bar becase a cable also is inside of the bar At the ground station, two electrical brushes get the electrical energy from the bar In fact the long bar transfer both electrical and also machnical energy', '6.png', 'The carbonbar transfers both electrical energy and mechanical energy from the floating circular structure to the ground', 'Considering a 10 meter diameter circular structure and thinkess of 4 meters, with GFSS turbine with diamtere of 3 meteres and lenght of 6 meters, the generated electricty at wind speed of 30km/h will be 18KWh. At very high speed the deviation angle of whole floating wind turbin to the ground will be low but it still will be at a high altitude and generates electricty according to calculations. A floating wind farm using such new floating windturbin also designed and its output power stimated. A wind farm with area of 1km x 1km with 200 number of such wind turbine can generate 3600Kwh in wind speed of 30k/h', 'The proposed wind turbine occupy lower area as it is floating at higher altitude and only the ground is on the ground occupy a small area Also this new wind turbin can be used to make floating wind farms that has minimum enviromental beauty effect  Because this wind turbin floating at higher altiutude and not visible from the ground This new wind turbin also generate more energy as it benefits high altitude winds that has higher wind speed and more consistent wind speed', 'Due to greenhouse problem of the fossile fules which are limitted as well, there is a active seeking for extraction of renewable energies because electrical energy consumption also increasing worldwide Renewable energy generation technologies including wind power, solar power, water power, biomass, and nuclear power has several problems of cost or low efficiency To alleviate these problems a new airborn floating wind turbine propsoed The wind turbin floats at high altitude and generates electrical energy The propsoed floating wind turbine system parts explained in detail and it output power estimated and also a floating wind farm using such floating wind turbine also considered and its output power estimated Finally advantage of this floating wind turbine are explained', 'White, N., Tierno, N., Garcia-Sanz, M', 'A novel approach to airborne wind energy: Design and modeling', 'Energytech, 2011 IEEE', '25-26 May 2011', 'L. Fagiano; M. Milanese', 'Airborne Wind Energy: An overview', 'IEEE Conf.  Montreal, QC, Canada', 'Vol.3 Issue.3', 'Lorenzo Fagiano, Mario Milanese, Dario Piga', 'Optimization of airborne wind energy generators', 'International Journal of Robust and Nonlinear Control', 'Vol.4, Issue.5', 'Ali Mardani, Saeed Askary', '', '', '', '', '', '', '', '', '', '', '', 1, 0, 1, '', '', '', '', '', ''),
(180, 'Article', 18, 'clamamagazine.com', '1', 'A-New-Hybrid-Transformer-with-Ability-to-Extract-Wind-Energy', '', 'A New Hybrid Transformer with Ability to Extract Wind Energy', '', 'Power transformer, wind power, wind turbine, distributed generation', 'The energy consumtion is increasing and energy generation is hard to increase A new power transformer with ability to extract wind energy proposed', 'The energy consumtion is increasing and energy generation is hard to increase', 'Over the time, more devices are changed from manual to automate using electrical energy Also, by increase in population, expansion of cities, industry the electrical energy consumption increases', 'The number of buildings, factories, electrical devices in cities increases Also population increases But creating an electrical energy generation station is hard because energy resources are limitted and the locations to deploy them need to satify many criterion For instance a water energy extraction station need to be constructed where damm is possible to be constructed', '', 'Electrical energy is essential for human life and most devices in houses, factoires, shops, city infrastrucres works with electricity', 'Almost, any building has several electrical devices and human work with and a part of his daily life relay on it Without electricty, many of automated actions should be done manually', 'If the electricity intrupted a large part of devices at cities, homes, factories, hospitals stope working', 'Electrical energy generation using fossile fules where fossile fules is burned to rotate an electrical generator', 'The generation of electrical energy by fossile fuels is in this way that first fossile fuel is burned to heat water to produce steam and the steam pressure rotate turbine connected to an electrical generator', 'The mass like uranium is converted to nuclear power is used to heat water and steam turns turbine to rotate generator to generate electricity', 'Special heavy masses like Uranium during a complex atomic procedure is disapeared and energy is released This energy is in form of heating warms up water produces steam to rotate turbine of electrical generator', 'Renewable energies such as wind, solar, water powers are extracted to generate electricity', 'To produce energies without CO2 emission solar energy, water power and wind energy is used to generate electricty', 'Fossile fules resources are limited and it also has greenhouse effects', 'Fossile fules when burned produce CO2 and other greenhouse gasses that causes pollution and also heat up the earth increase its temprature', 'The fossile fules extraction, delivery, and burning is costy and also the resulted CO2 has adverse effect on environment', 'The trash produced by nuclear power stations should be buried but they are dangrous for human, and animal and enviroment', 'The nuclear power station heart is called reactor The reactor produces readio active materials that emits gamma and x rays and are dangrous for biological creaters like human', 'The nuclear power station is expensive to construct and also expensive in operation, and maintanance', 'Renewable energy generators still a few and more variations of them is needed to be used in different ways', 'The renewable energy technology is not developed enough and is not mature Still more improvment is renewable energy generators is needed and more types of them need to be invented for different places and situation', 'These renewable energies is easy to extract but the amount of extracted energy is not significant and more number of such generators should built', 'A new power transformer with ability to extract wind energy proposed', '', '', 'The transfomer will have a structure that is electrical generator and electrical transformer at the same time A wind turbin is connected to the transfomer shaft', 'It not only works as transformer but also extract wind energy and it has low cost compared to conventional wind turbines', '', 'The transformer role is just to increase or decrease voltage but this transformer also generate electricity and adds to the network', 'It can be electrical distrubution centers, power generation centers where wind turbine was not used but now can be used  ', '', 'The transformer role is just to increase or decrease voltage but this transformer also generate electricity and adds to the network', 'The transformer consisted for several part The first part is the main iron core. This core is rectangular core which has circular structure inside. The internal circular structure has poles these pole are poles of the electrical generator', 'The-iron-core-of-the-electrical-generator-which-has-poles-inside-as-pole-of-electrical-generator-.png', 'The iron core of the electrical generator which has poles inside as pole of electrical generator ', 'The primary winding is on the left side  as shown in Fig.2.  This transformer is a two phase transformer', 'The-primary-and-secondary-winding.png', 'The primary and secondary winding', 'The secondary winding is on the right side as shown in Fig. 3.  There are 8 poles the winding of four poles connected to the primary winding and windings of the rest four poles connected to the secondary winding. In fact the primary and secondary windings are still not connected and are isolated. ', 'The-pole-which-play-role-of-generator-poles-has-windings-connected-to-the-primary-and-secondary-windings.png', 'The pole which play role of generator poles has windings connected to the primary and secondary windings', 'The rotor of the generator is a circular shaped with magnet poles on it. The rotor rotate inside of the core of the transformer. The core of the transformer plays role of the stator of the generator and core of transformer at the same time.', 'The-rotor-of-the-generator-rotates-inside-of-core-of-the-transformer-.png', 'The rotor of the generator rotates inside of core of the transformer ', 'The poles of the rotor of the generator are coupled magnetically with poles of the stator as shown in Fig. 5.', 'The-electrical-simplified-model-of-the-hybrid-transformer-generator.png', 'The electrical simplified model of the hybrid transformer-generator', 'The wind turbine is connected to the shaft of the rotor. The wind blows and the wind turbine rotates the rotor inside the stator generates electricity as shown in Fig. 6', 'The-wind-turbin-connected-to-the-rotor-rotates-the-rotor.png', 'The wind turbin connected to the rotor rotates the rotor', 'This transformer convert transfer the electrical energy also add electrical energy to the transferred energy. The electrical circuit model of the hybrid transformer generator shown in Fig. 7', 'The-formula-for-transfer-and-conversion-process-in-the-hybrid-transformer-generator.png', 'The formula for transfer and conversion process in the hybrid transformer generator', '', 'The transformer already has foundation and ground area devoted to it this reduces the wind power system cost as it befits the found and ground area of the electrical transformer. Also, the generated wind energy from conventional wind turbines needs to be transferred via cables and transmission lines to the nearest distribution system, but in this new system, the wind energy is generated where distribution happens not delivering is needed', 'Electrical energy consumption rate is incremental and there is an active seeking for electrical energy generation. To generate electrical energy an new hybrid transformer generator is designed and proposed. The transformer-generator not only changes the violate of electrical energy but also it generate electrical energy as a wind turbine connected to it rotates its shaft All parts of the proposed transformer-generator illustrated . The advantages of the proposed system also described', 'Christoph Krause', 'Power transformer insulation – history, technology and design', 'IEEE Transactions on Dielectrics and Electrical Insulation', 'Volume: 19, Issue: 6', 'G.M. Joselin Herbert, S. Iniyan', 'A review of wind energy technologies', 'Renewable and Sustainable Energy Reviews', 'Volume: 9, Issue: 3', 'Gopal Singh , and Kalpathy Sundaram', 'Manufacturing deformation impact on the performance of electrical generator for the wind turbine application', 'Wind Engineering', 'Volume: 14, Issue: 6', 'Thomas Kelly, Johan Siriy', '', '', '', '', '', '', '', '', '', '', '', 0, 0, 1, '', '', '', '', '', '');
