('cbdix.fr', 1, 'CBDIX France', 1, 0, '{\"contact\":null,\"about\":null,\"privacy\":\"on\",\"terms_conditions\":null}', '[1,0,0,1,1,0,0]', '3', '28', '', 'Lorem Ipsum Press is licensed by Bionetwork Ltd. Our office is located within the company\'s building.\r\n<br>\r\nAddress:<br>\r\nKeas 69 Str.<br>\r\n15234, Chalandri<br>\r\nAthens,<br>\r\nGreece<br>\r\n+30-2106019311 (landline)<br>\r\n+30-6977664062 (mobile phone)<br>\r\n+30-2106398905 (fax)<br>\r\n', '', 'This is Terms and Condition page of the website. You still did not set any content in this page. You can edit this page and add any HTML content here.', '', '', '', 'auto', '', '', '100%', '', '', 'auto', '', '', 'auto', '', '', 'auto', '', '', 'auto', '', '', 'auto', '', '', 'auto', '<br>The homepage of cbdix.fr was slow with loading time of 2.4ms at May 24 2023 11:22 for user with IP: 34.219.202.158', 'blog'),
('cbd-mania.fr', 2, 'CBD Mania Review', 1, 1, '0', '[0,1,0,1,1,1,0]', '1', '8', 'This is about section. You can modify it.', 'This is a test', '', '', '', '', '', 'auto', '', '6', '50%', '', '', 'auto', '', '', 'auto', '', '', '50%', '', '', 'auto', '', '', 'auto', '', '', 'auto', '<br>The homepage of cbd-mania.fr was slow with loading time of 1.6ms at May 09 2023 06:16 for user with IP: 178.128.104.131', 'blog'),
('clamamagazine.com', 3, 'Clama Magazine', 1, 1, '{\"contact\":null,\"about\":null,\"privacy\":null,\"terms_conditions\":\"on\"}', '', '', '8', 'Clama Magazine of Energy is a scientific journal about energy. It focuses primarily on enery generation, energy saving and storage, energy conversion in iterndescpinary area. It is published by the Progress Science Press, Clama Magazine of Energy is an electronic journal with free access to the full text available in the website (https://clamamagazine.com/).  It contains articles authored by scholars and specialists.  We welcome paprs in French and English.', 'Lorem Ipsum Press is licensed by Bionetwork Ltd. Our office is located within the company\'s building.\n<br>\nAddress:<br>\nKeas 69 Str.<br>\n15234, Chalandri<br>\nAthens<br>\nGreece<br>\n+30-2106019311 (landline)<br>\n+30-6977664062 (mobile phone)<br>\n+30-2106398905 (fax)<br>\n', '', '', '', '', '', 'auto', '', '', 'auto', '', '', 'auto', '', '', 'auto', '', '', 'auto', '', '', 'auto', '', '', 'auto', '', '', 'auto', '', 'magazine'),
